#include "../wfas.c"
#include "vectors.h"

#include <stdio.h>

static uint32_t g_run;
static uint32_t g_fail;

static void check(uint32_t cond, const char *what)
{
    g_run += 1U;
    if (cond != 1U) {
        g_fail += 1U;
        (void)printf("FAIL: %s\n", what);
    }
}

static uint32_t eq(const uint8_t *a, const uint8_t *b, size_t n)
{
    return wfas3_ct_eq(a, b, n);
}

static uint32_t all_zero(const uint8_t *a, size_t n)
{
    uint32_t acc = 0U;
    size_t i;

    for (i = 0U; i < n; i++) {
        acc |= (uint32_t)a[i];
    }
    return (acc == 0U) ? 1U : 0U;
}

static void test_hash_mac_kdf(void)
{
    uint8_t out[96];
    uint8_t ctx[24];
    size_t i;

    wfas_tp_sha256(out, v_msg, (uint32_t)sizeof v_msg);
    check(eq(out, v_sha256, 32U), "sha256");
    wfas_tp_sha512(out, v_msg, (uint32_t)sizeof v_msg);
    check(eq(out, v_sha512, 64U), "sha512");
    wfas_tp_hmac_sha256(out, v_key, 32U, v_msg, (uint32_t)sizeof v_msg);
    check(eq(out, v_hmac, 32U), "hmac");
    wfas_tp_hkdf_extract(out, v_key, 32U, v_msg, (uint32_t)sizeof v_msg);
    check(eq(out, v_hkdf_prk, 32U), "hkdf extract");
    wfas_tp_hkdf_expand(out, 80U, v_hkdf_prk, v_msg, 20U);
    check(eq(out, v_hkdf_okm, 80U), "hkdf expand");

    check((wfas3_kdf(out, 32U, v_key, WFAS3_LBL("transport i2r"), NULL, 0U) == WFAS3_OK) ? 1U : 0U, "kdf status");
    check(eq(out, v_kdf, 32U), "kdf label");
    for (i = 0U; i < sizeof ctx; i++) {
        ctx[i] = (uint8_t)(0x05U + i);
    }
    check((wfas3_kdf(out, 32U, v_key, WFAS3_LBL("cookie"), ctx, sizeof ctx) == WFAS3_OK) ? 1U : 0U, "kdf ctx status");
    check(eq(out, v_kdf_ctx, 32U), "kdf label and context");
    check((wfas3_kdf(out, 0U, v_key, WFAS3_LBL("x"), NULL, 0U) == WFAS3_E_ARG) ? 1U : 0U, "kdf zero length");
    check((wfas3_kdf(out, 97U, v_key, WFAS3_LBL("x"), NULL, 0U) == WFAS3_E_ARG) ? 1U : 0U, "kdf too long");
    check((wfas3_kdf(out, 32U, v_key, WFAS3_LBL("x"), v_msg, 49U) == WFAS3_E_ARG) ? 1U : 0U, "kdf context too long");

    check((wfas3_mac(out, 16U, v_key, v_msg, sizeof v_msg) == WFAS3_OK) ? 1U : 0U, "mac16 status");
    check(eq(out, v_mac16, 16U), "mac16");
    check((wfas3_mac(out, 8U, v_key, v_msg, sizeof v_msg) == WFAS3_OK) ? 1U : 0U, "mac8 status");
    check(eq(out, v_mac16, 8U), "mac8");
    check((wfas3_mac(out, 12U, v_key, v_msg, sizeof v_msg) == WFAS3_E_ARG) ? 1U : 0U, "mac bad length");
}

static void test_x25519(void)
{
    uint8_t out[32];
    uint8_t zero[32];

    wfas_tp_x25519_public(out, v_x_a_priv);
    check(eq(out, v_x_a_pub, 32U), "x25519 public a");
    wfas_tp_x25519_public(out, v_x_b_priv);
    check(eq(out, v_x_b_pub, 32U), "x25519 public b");
    check(wfas_tp_x25519(out, v_x_a_priv, v_x_b_pub), "x25519 a*B status");
    check(eq(out, v_x_shared, 32U), "x25519 a*B");
    check(wfas_tp_x25519(out, v_x_b_priv, v_x_a_pub), "x25519 b*A status");
    check(eq(out, v_x_shared, 32U), "x25519 b*A");
    memset(zero, 0, sizeof zero);
    check(1U ^ wfas_tp_x25519(out, v_x_a_priv, zero), "x25519 rejects the zero point");
    zero[0] = 1U;
    check(1U ^ wfas_tp_x25519(out, v_x_a_priv, zero), "x25519 rejects the point of order 1");
}

static void test_aead(void)
{
    uint8_t ct[116];
    uint8_t pt[100];
    uint8_t ad[16];
    const uint64_t n = 0x0102030405060708ULL;

    memcpy(ad, v_ad, sizeof ad);
    check((wfas3_seal(ct, sizeof ct, v_key, n, ad, sizeof ad, v_msg, sizeof v_msg) == WFAS3_OK) ? 1U : 0U, "seal status");
    check(eq(ct, v_sealed, sizeof ct), "seal matches the reference");
    check((wfas3_open(pt, sizeof pt, v_key, n, ad, sizeof ad, ct, sizeof ct) == WFAS3_OK) ? 1U : 0U, "open status");
    check(eq(pt, v_msg, sizeof pt), "open returns the plaintext");

    ct[115] ^= 0x80U;
    memset(pt, 0xAA, sizeof pt);
    check((wfas3_open(pt, sizeof pt, v_key, n, ad, sizeof ad, ct, sizeof ct) == WFAS3_E_AUTH) ? 1U : 0U, "open rejects a forged tag");
    check(all_zero(pt, sizeof pt), "output erased after a forged tag");
    ct[115] ^= 0x80U;
    ct[3] ^= 0x01U;
    check((wfas3_open(pt, sizeof pt, v_key, n, ad, sizeof ad, ct, sizeof ct) == WFAS3_E_AUTH) ? 1U : 0U, "open rejects a changed ciphertext");
    ct[3] ^= 0x01U;
    ad[0] ^= 0x01U;
    check((wfas3_open(pt, sizeof pt, v_key, n, ad, sizeof ad, ct, sizeof ct) == WFAS3_E_AUTH) ? 1U : 0U, "open rejects changed associated data");
    ad[0] ^= 0x01U;
    check((wfas3_open(pt, sizeof pt, v_key, n + 1U, ad, sizeof ad, ct, sizeof ct) == WFAS3_E_AUTH) ? 1U : 0U, "open rejects another counter");
    check((wfas3_open(pt, sizeof pt, v_key, n, ad, sizeof ad, ct, 15U) == WFAS3_E_ARG) ? 1U : 0U, "open rejects a short input");
    check((wfas3_open(pt, 99U, v_key, n, ad, sizeof ad, ct, sizeof ct) == WFAS3_E_ARG) ? 1U : 0U, "open rejects a small output");
    check((wfas3_seal(ct, 115U, v_key, n, ad, sizeof ad, v_msg, sizeof v_msg) == WFAS3_E_ARG) ? 1U : 0U, "seal rejects a small output");

    check((wfas3_seal(ct, sizeof ct, v_key, 0U, ad, sizeof ad, v_msg, 0U) == WFAS3_OK) ? 1U : 0U, "seal empty status");
    check(eq(ct, v_sealed_empty, 16U), "seal of an empty plaintext");
    check((wfas3_open(pt, sizeof pt, v_key, 0U, ad, sizeof ad, ct, 16U) == WFAS3_OK) ? 1U : 0U, "open empty");
}

static void test_mlkem(void)
{
    static uint8_t pk[WFAS_TP_MLKEM_PK];
    static uint8_t sk[WFAS_TP_MLKEM_SK];
    static uint8_t ct[WFAS_TP_MLKEM_CT];
    uint8_t ss[32];
    uint8_t ss2[32];
    uint8_t h[32];
    size_t i;

    wfas_tp_mlkem768_keygen(pk, sk, v_kem_rnd);
    wfas_tp_sha256(h, pk, (uint32_t)sizeof pk);
    check(eq(h, v_kem_pk_hash, 32U), "ml-kem encapsulation key");
    wfas_tp_sha256(h, sk, (uint32_t)sizeof sk);
    check(eq(h, v_kem_sk_hash, 32U), "ml-kem decapsulation key");
    check(wfas_tp_mlkem768_check_pk(pk), "ml-kem key check accepts a valid key");
    wfas_tp_mlkem768_encaps(ct, ss, pk, v_kem_m);
    wfas_tp_sha256(h, ct, (uint32_t)sizeof ct);
    check(eq(h, v_kem_ct_hash, 32U), "ml-kem ciphertext");
    check(eq(ss, v_kem_ss, 32U), "ml-kem shared secret (encaps)");
    wfas_tp_mlkem768_decaps(ss2, ct, sk);
    check(eq(ss2, v_kem_ss, 32U), "ml-kem shared secret (decaps)");
    ct[0] ^= 0x01U;
    wfas_tp_mlkem768_decaps(ss2, ct, sk);
    check(eq(ss2, v_kem_ss_reject, 32U), "ml-kem implicit rejection");
    check(1U ^ eq(ss2, v_kem_ss, 32U), "ml-kem changed ciphertext gives another secret");
    for (i = 0U; i < 1152U; i++) {
        pk[i] = 0xFFU;
    }
    check(1U ^ wfas_tp_mlkem768_check_pk(pk), "ml-kem key check rejects unreduced coefficients");
}

static void test_drbg(void)
{
    wfas3_rng r;
    uint8_t out[64];
    uint8_t ent[32];
    size_t i;

    r.ready = 0U;
    check((wfas3_rng_bytes(&r, out, 32U) == WFAS3_E_ENTROPY) ? 1U : 0U, "rng refuses to run without entropy");
    check((wfas3_rng_reseed(&r, v_key) == WFAS3_E_ENTROPY) ? 1U : 0U, "rng refuses a reseed before start");
    wfas3_rng_start(&r, v_drbg_seed);
    check((wfas3_rng_bytes(&r, out, 64U) == WFAS3_OK) ? 1U : 0U, "rng status");
    check(eq(out, v_drbg_1, 64U), "rng first output");
    for (i = 0U; i < sizeof ent; i++) {
        ent[i] = (uint8_t)(0x99U + i);
    }
    check((wfas3_rng_reseed(&r, ent) == WFAS3_OK) ? 1U : 0U, "rng reseed");
    check((wfas3_rng_bytes(&r, out, 48U) == WFAS3_OK) ? 1U : 0U, "rng status after reseed");
    check(eq(out, v_drbg_2, 48U), "rng output after reseed");
    check((wfas3_rng_bytes(&r, out, 65U) == WFAS3_E_ENTROPY) ? 1U : 0U, "rng refuses a large request");
    check((wfas3_rng_bytes(&r, out, 0U) == WFAS3_E_ENTROPY) ? 1U : 0U, "rng refuses an empty request");
}

static void test_sym(void)
{
    wfas3_sym s;
    wfas3_sym t;
    wfas3_sym before;
    uint8_t ct[64];
    uint8_t ct2[16];
    uint8_t pt[48];

    check((wfas3_sym_init(&s, WFAS3_LBL("WFAS3_KKpsk0hfs_25519+MLKEM768_ChaChaPoly_SHA256")) == WFAS3_OK) ? 1U : 0U, "sym init");
    check((wfas3_sym_encrypt(&s, ct, sizeof ct, v_msg, 48U) == WFAS3_E_ARG) ? 1U : 0U, "sym refuses to encrypt without a key");
    check((wfas3_sym_mix_key_and_hash(&s, v_key) == WFAS3_OK) ? 1U : 0U, "sym mix key and hash");
    check((wfas3_sym_mix_hash(&s, v_msg, sizeof v_msg) == WFAS3_OK) ? 1U : 0U, "sym mix hash");
    check((wfas3_sym_mix_key(&s, v_msg, 32U) == WFAS3_OK) ? 1U : 0U, "sym mix key");
    t = s;
    check((wfas3_sym_encrypt(&s, ct, sizeof ct, v_msg, 48U) == WFAS3_OK) ? 1U : 0U, "sym encrypt");
    check(eq(ct, v_sym_ct, sizeof ct), "sym first ciphertext");
    check((wfas3_sym_encrypt(&s, ct2, sizeof ct2, v_msg, 0U) == WFAS3_OK) ? 1U : 0U, "sym encrypt empty");
    check(eq(ct2, v_sym_ct2, sizeof ct2), "sym second ciphertext");
    check(eq(s.h, v_sym_h, 32U), "sym transcript hash");
    check(eq(s.ck, v_sym_ck, 32U), "sym chaining key");

    before = t;
    ct[5] ^= 0x04U;
    check((wfas3_sym_decrypt(&t, pt, sizeof pt, ct, sizeof ct) == WFAS3_E_AUTH) ? 1U : 0U, "sym decrypt rejects a changed message");
    check(eq(t.h, before.h, 32U) & ((t.n == before.n) ? 1U : 0U), "sym state unchanged after a rejected message");
    ct[5] ^= 0x04U;
    check((wfas3_sym_decrypt(&t, pt, sizeof pt, ct, sizeof ct) == WFAS3_OK) ? 1U : 0U, "sym decrypt");
    check(eq(pt, v_msg, sizeof pt), "sym decrypt returns the plaintext");
    check((wfas3_sym_decrypt(&t, pt, sizeof pt, ct2, sizeof ct2) == WFAS3_OK) ? 1U : 0U, "sym decrypt empty");
    check(eq(t.h, s.h, 32U), "both sides reach the same transcript hash");
    check((wfas3_sym_mix_hash(&s, v_msg, 1281U) == WFAS3_E_ARG) ? 1U : 0U, "sym mix hash bound");
    check((wfas3_sym_mix_key(&s, v_msg, 0U) == WFAS3_E_ARG) ? 1U : 0U, "sym mix key refuses empty input");
    wfas3_sym_wipe(&s);
    check(all_zero(s.k, 32U) & all_zero(s.ck, 32U) & all_zero(s.h, 32U), "sym wipe");
}

static void try_len(uint8_t type, size_t len, uint32_t want, const char *what)
{
    static uint8_t d[WFAS3_MAX_DATAGRAM + 8U];
    uint8_t t = 0U;
    wfas3_status st;

    memset(d, 0, sizeof d);
    d[0] = WFAS3_MARKER;
    d[1] = type;
    st = wfas3_classify(d, len, &t);
    check((((st == WFAS3_OK) && (t == type)) ? 1U : 0U) == want, what);
}

static void test_classify(void)
{
    static const uint16_t exact[][2] = {
        { WFAS3_T_PROBE, 60U }, { WFAS3_T_PROBE_REPLY, 60U }, { WFAS3_T_PAIR_BEACON, 72U },
        { WFAS3_T_INIT, 1368U }, { WFAS3_T_RESP, 1228U }, { WFAS3_T_COOKIE_REPLY, 64U },
        { WFAS3_T_COOKIE_REQUEST, 64U }, { WFAS3_T_REJECT, 48U },
        { WFAS3_T_PAIR, 1368U }, { WFAS3_T_PAIR, 1296U }, { WFAS3_T_PAIR, 176U },
        { WFAS3_T_PAIR, 120U }, { WFAS3_T_PAIR, 100U }, { WFAS3_T_PAIR, 80U }, { WFAS3_T_PAIR, 52U }
    };
    uint8_t d[64];
    uint8_t t = 0U;
    size_t i;
    uint32_t type;

    for (i = 0U; i < (sizeof exact / sizeof exact[0]); i++) {
        try_len((uint8_t)exact[i][0], exact[i][1], 1U, "exact length accepted");
        try_len((uint8_t)exact[i][0], (size_t)exact[i][1] - 1U, 0U, "one byte short dropped");
        try_len((uint8_t)exact[i][0], (size_t)exact[i][1] + 1U, 0U, "one byte long dropped");
    }
    try_len(WFAS3_T_TRANSPORT, 160U, 1U, "control packet");
    try_len(WFAS3_T_TRANSPORT, 56U, 1U, "smallest audio packet");
    try_len(WFAS3_T_TRANSPORT, 55U, 0U, "audio packet without payload");
    try_len(WFAS3_T_TRANSPORT, 1399U, 1U, "largest audio packet");
    try_len(WFAS3_T_TRANSPORT, 1400U, 0U, "audio packet too large");
    try_len(WFAS3_T_MULTICAST, 188U, 1U, "smallest multicast packet");
    try_len(WFAS3_T_MULTICAST, 187U, 0U, "multicast packet without payload");
    try_len(WFAS3_T_MULTICAST, 1400U, 1U, "largest multicast packet");
    try_len(WFAS3_T_MULTICAST, 1401U, 0U, "datagram above the maximum");
    for (type = 0U; type < 256U; type++) {
        uint32_t known = ((type >= 1U) && (type <= 3U)) || ((type >= 0x10U) && (type <= 0x15U)) ||
                         (type == 0x20U) || (type == 0x30U);
        if (known == 0U) {
            try_len((uint8_t)type, 64U, 0U, "unknown type dropped");
        }
    }

    memset(d, 0, sizeof d);
    d[0] = WFAS3_MARKER;
    d[1] = WFAS3_T_COOKIE_REQUEST;
    check((wfas3_classify(d, 64U, &t) == WFAS3_OK) ? 1U : 0U, "well-formed header");
    d[0] = 0x57U;
    check((wfas3_classify(d, 64U, &t) == WFAS3_E_DROP) ? 1U : 0U, "v2 first byte dropped");
    d[0] = WFAS3_MARKER;
    d[2] = 1U;
    check((wfas3_classify(d, 64U, &t) == WFAS3_E_DROP) ? 1U : 0U, "non-zero flag byte dropped");
    d[2] = 0U;
    d[3] = 0x80U;
    check((wfas3_classify(d, 64U, &t) == WFAS3_E_DROP) ? 1U : 0U, "non-zero reserved byte dropped");
    d[3] = 0U;
    check((wfas3_classify(d, 3U, &t) == WFAS3_E_DROP) ? 1U : 0U, "shorter than the header dropped");
    check((wfas3_classify(NULL, 64U, &t) == WFAS3_E_ARG) ? 1U : 0U, "null datagram");
    check((wfas3_classify(d, 64U, NULL) == WFAS3_E_ARG) ? 1U : 0U, "null output");
}

static void test_misc(void)
{
    static uint8_t big[WFAS3_CMP_MAX + 1U];
    uint8_t a[40];
    uint8_t b[40];
    uint8_t be[8];
    static const uint8_t want[8] = { 0x01U, 0x02U, 0x03U, 0x04U, 0x05U, 0x06U, 0x07U, 0x08U };
    size_t i;

    memset(a, 0x5A, sizeof a);
    memset(b, 0x5A, sizeof b);
    check(wfas3_ct_eq(a, b, sizeof a), "ct_eq equal");
    check(wfas3_ct_eq(a, b, 0U), "ct_eq empty");
    for (i = 0U; i < sizeof a; i++) {
        b[i] ^= 0x01U;
        check(1U ^ wfas3_ct_eq(a, b, sizeof a), "ct_eq sees every position");
        b[i] ^= 0x01U;
    }
    b[39] = 0xDAU;
    check(1U ^ wfas3_ct_eq(a, b, sizeof a), "ct_eq sees the top bit");
    check(1U ^ wfas3_ct_eq(big, big, sizeof big), "ct_eq fails closed above its bound");
    wfas3_wipe(a, sizeof a);
    check(all_zero(a, sizeof a), "wipe");
    wfas3_wr_be64(be, 0x0102030405060708ULL);
    check(eq(be, want, 8U), "big-endian u64");
    check(eq(v_selftest, v_selftest, 16U), "vector table present");
    check((wfas3_selftest() == WFAS3_OK) ? 1U : 0U, "power-on self-test matches the reference");
}

/* Elligator 2 against RFC 9380 J.4 and against the Python reference (both
 * branches, edge values, bit 255 set); CPace against draft-21 B.1. */
static void test_ell2_cpace(void)
{
    uint8_t out[64];
    uint8_t g[32];
    uint8_t ya[32];
    uint8_t yb[32];
    uint8_t k1[32];
    uint8_t k2[32];
    uint32_t i;
    uint32_t ok;

    for (i = 0U; i < V_ELL2_RFC_COUNT; i++) {
        wfas3_ell2(out, &v_ell2_rfc_in[32U * i]);
        check(eq(out, &v_ell2_rfc_out[32U * i], 32U), "Elligator 2: RFC 9380 J.4 vector");
    }
    for (i = 0U; i < V_ELL2_COUNT; i++) {
        wfas3_ell2(out, &v_ell2_in[32U * i]);
        check(eq(out, &v_ell2_out[32U * i], 32U), "Elligator 2: reference value");
    }
    check((wfas3_cpace_gen(g, v_cpace_PRS, sizeof v_cpace_PRS, v_cpace_CI, sizeof v_cpace_CI,
                           v_cpace_sid, sizeof v_cpace_sid) == WFAS3_OK) ? 1U : 0U, "CPace generator");
    check(eq(g, v_cpace_g, 32U), "CPace: generator g of draft-21");
    check(wfas_tp_x25519(ya, v_cpace_ya, g), "CPace: Ya computed");
    check(eq(ya, v_cpace_Ya, 32U), "CPace: Ya of draft-21");
    check(wfas_tp_x25519(yb, v_cpace_yb, g), "CPace: Yb computed");
    check(eq(yb, v_cpace_Yb, 32U), "CPace: Yb of draft-21");
    check(wfas_tp_x25519(k1, v_cpace_ya, yb) & wfas_tp_x25519(k2, v_cpace_yb, ya), "CPace: K");
    check(eq(k1, v_cpace_K, 32U) & eq(k2, v_cpace_K, 32U), "CPace: K of draft-21, both sides");
    check((wfas3_cpace_isk(out, v_cpace_sid, sizeof v_cpace_sid, k1, ya, v_cpace_ADa,
                           sizeof v_cpace_ADa, yb, v_cpace_ADb, sizeof v_cpace_ADb) == WFAS3_OK)
          ? 1U : 0U, "CPace ISK");
    check(eq(out, v_cpace_ISK, 64U), "CPace: ISK of draft-21");
    for (i = 0U; i < V_CPACE_LOW_COUNT; i++) {
        ok = wfas_tp_x25519(out, v_cpace_low_s, &v_cpace_low_u[32U * i]);
        if (all_zero(&v_cpace_low_q[32U * i], 32U) == 1U) {
            check(1U ^ ok, "CPace: low-order point aborts");
        } else {
            check(ok & eq(out, &v_cpace_low_q[32U * i], 32U), "CPace: non-canonical point, bit 255 cleared");
        }
    }
    check((wfas3_cpace_gen(g, v_ell2_in, 16U, (const uint8_t *)"WFAS3-PAIR\x01", 11U,
                           v_ell2_in, 24U) == WFAS3_OK) ? 1U : 0U, "generator of a code");
    check((wfas3_cpace_gen(g, v_ell2_in, 65U, v_cpace_CI, 11U, v_cpace_sid, 16U) == WFAS3_E_ARG)
          ? 1U : 0U, "generator: PRS too long refused");
}

int main(void)
{
    test_hash_mac_kdf();
    test_x25519();
    test_aead();
    test_mlkem();
    test_drbg();
    test_sym();
    test_classify();
    test_misc();
    test_ell2_cpace();
    (void)printf("%u checks, %u failed\n", (unsigned)g_run, (unsigned)g_fail);
    return (g_fail == 0U) ? 0 : 1;
}
